    public function run(): void
    {
        AuditLog::withoutRecording(function (): void {
            TransportViolation::withTrashed()->forceDelete();

            $now = now();
            $payload = [];

            foreach (self::rows() as $row) {
                $payload[] = [
                    'violation_number' => $row[0],
                    'record_holder' => $row[1],
                    'violation_date' => $row[2],
                    'amount' => $row[3],
                    'department' => $row[4],
                    'city' => $row[5],
                    'violation_description' => $row[6],
                    'objection_status' => $row[7],
                    'plate_number' => $row[8],
                    'equipment_code' => $row[9],
                    'driver_name' => $row[10],
                    'employee_id' => $row[11],
                    'employee_status' => $row[12],
                    'liability' => $row[13],
                    'permit_status' => $row[14],
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
            }

            foreach (array_chunk($payload, 50) as $chunk) {
                TransportViolation::query()->insert($chunk);
            }
        });

        DashboardService::clearCache();
    }
